  fidl::internal::NaturalEventDispatcher<::fuchsia_io::File>::DispatchEvent(
      ::fidl::IncomingHeaderAndMessage& msg,
      ::fidl::internal::MessageStorageViewBase* storage_view) {
    switch (msg.header()->ordinal) {
      case ::fuchsia_io::kFile_OnOpen_Ordinal:
      {
        ::fit::result decoded = ::fidl::internal::DecodeTransactionalMessage<::fuchsia_io::NodeOnOpenRequest>(std::move(msg));
        if (decoded.is_error()) {
          return decoded.error_value();
        }
        if (event_handler()) {
            ::fidl::Event<::fuchsia_io::File::OnOpen> event = std::move(decoded.value());
          event_handler()->OnOpen(event);
        }
        return ::fidl::Status::Ok();
      }
      case ::fuchsia_io::kFile_OnRepresentation_Ordinal:
      {
        ::fit::result decoded = ::fidl::internal::DecodeTransactionalMessage<::fuchsia_io::Representation>(std::move(msg));
        if (decoded.is_error()) {
          return decoded.error_value();
        }
        if (event_handler()) {
            ::fidl::Event<::fuchsia_io::File::OnRepresentation> event = std::move(decoded.value());
          event_handler()->OnRepresentation(event);
        }
        return ::fidl::Status::Ok();
      }
      default:
        auto* hdr = msg.header();
        ::fidl::UnknownMethodType unknown_method_type =
            ::fidl::internal::UnknownMethodTypeFromHeader(hdr);
        bool is_flexible_interaction = ::fidl::IsFlexibleInteraction(hdr);
        auto ordinal = hdr->ordinal;
        std::move(msg).CloseHandles();
        if (is_flexible_interaction &&
            ::fidl::internal::CanHandleEvent(::fuchsia_io::File::kOpenness, unknown_method_type)) {
          if (event_handler()) {
            ::fidl::UnknownEventMetadata<::fuchsia_io::File> metadata {
              .event_ordinal = ordinal,
            };
            event_handler()->handle_unknown_event(metadata);
          }
          return ::fidl::Status::Ok();
        }
        return ::fidl::Status::UnknownOrdinal();
    }
  }

